      'description' => 'किसी मेहमान के बारे में क्या बताया जा सकता है और क्या नहीं, कमरा नंबर को लेकर अनुशासन और तीसरे पक्ष की पूछताछ को संभालना। यह कोर्स उस प्रक्रिया के इर्द-गिर्द बनाया गया है जैसी वह शिफ़्ट पर वास्तव में की जाती है, जिसमें एक लिखित मानक, आम गलतियाँ और पूरी करने के लिए एक चेकलिस्ट शामिल है।',
