      'description' => 'दोनों भाषाओं में समीक्षाओं का जवाब देना, फ़ीडबैक में परिचालन से जुड़ा पैटर्न पहचानना और मामले को अंजाम तक पहुँचाना। यह कोर्स उस प्रक्रिया के इर्द-गिर्द बनाया गया है जैसी वह शिफ़्ट पर वास्तव में की जाती है, जिसमें एक लिखित मानक, आम गलतियाँ और पूरी करने के लिए एक चेकलिस्ट शामिल है।',
