  'pages' => 
  array (
    'home' => 
    array (
      'title' => 'Hospitality Academy: सऊदी अरब में होटल स्टाफ प्रशिक्षण',
      'subtitle' => 'रियाद स्थित Altus Advisory की ओर से होटल टीमों के लिए भूमिका-आधारित प्रशिक्षण, व्यावहारिक मूल्यांकन और सत्यापन-योग्य प्रमाणन। अरबी, अंग्रेज़ी और उन भाषाओं में जो आपके कर्मचारी बोलते हैं।',
      'body' => '<h2>Hospitality Academy क्या है?</h2><p>Hospitality Academy, Altus Advisory की सार्वजनिक प्रशिक्षण अकादमी है, जो रियाद, सऊदी अरब में स्थित एक हॉस्पिटैलिटी और बिज़नेस रणनीति फ़र्म है। यह altus Hospitality Knowledge &amp; Performance प्लेटफ़ॉर्म पर चलती है, जो नौकरी की भूमिका के अनुसार होटल स्टाफ प्रशिक्षण देता है और फिर जाँचता है कि हर व्यक्ति वास्तव में काम कर सकता है या नहीं।</p><h2>यह एक सामान्य ऑनलाइन कोर्स से कैसे अलग है?</h2><p>कोर्स पूरा करने को प्रमाण नहीं माना जाता। हर शिक्षार्थी भूमिका-आधारित सीखने से सैद्धांतिक और व्यावहारिक मूल्यांकन की ओर बढ़ता है, और परिणाम परिभाषित दक्षताओं के सामने दर्ज किया जाता है। जहाँ कोई कमी दिखती है, वहाँ एक कार्य योजना और पुनर्मूल्यांकन होता है, ताकि प्रबंधक पूरे किए गए वीडियो की सूची के बजाय क्षमता का प्रमाण देखें।</p><ol><li>नौकरी की भूमिका की आवश्यकताओं के आधार पर सौंपा गया प्रशिक्षण</li><li>एक ही मानक पर सैद्धांतिक मूल्यांकन और व्यावहारिक मूल्यांकन</li><li>दक्षता रिकॉर्ड, पहचानी गई कमियाँ और सुधारात्मक कार्य योजना</li><li>पुनर्मूल्यांकन, तैयारी की स्थिति और सत्यापन-योग्य प्रमाणपत्र</li></ol><h2>अकादमी होटल के किन विभागों को कवर करती है?</h2><p>मुख्य पाठ्यक्रम दस प्रमुख पेशेवर क्षेत्रों में व्यवस्थित है: होटल के मूल सिद्धांत, फ्रंट ऑफ़िस, हाउसकीपिंग, फ़ूड एंड बेवरेज, किचन, सेल्स और मार्केटिंग, रेवेन्यू और आरक्षण, अतिथि अनुभव, गुणवत्ता और ऑडिट, तथा सुरक्षा और संरक्षा। <a href="/en/courses">कोर्स कैटलॉग</a> देखें या किसी विशेष भूमिका के लिए एक संरचित <a href="/en/learning-paths">लर्निंग पाथ</a> अपनाएँ।</p><h2>होटल स्टाफ किन भाषाओं में सीख सकते हैं?</h2><p>अरबी और अंग्रेज़ी एक ही अनुभव के रूप में शामिल हैं, और अरबी दाएँ से बाएँ प्रदर्शित होती है। स्टाफ वर्कस्पेस हिंदी, उर्दू, फ़िलिपिनो, बांग्ला, नेपाली और मलयालम को भी सपोर्ट करता है, ताकि हर शिफ़्ट में सेवा देने वाले लोग मानक को समझें।</p><h2>क्या कोई नियोक्ता प्रमाणपत्र की जाँच कर सकता है?</h2><p>हाँ। हर प्रमाणपत्र पर एक अद्वितीय नंबर और सत्यापन कोड होता है, और कोई भी <a href="/en/verify">प्रमाणपत्र सत्यापन पेज</a> पर पुष्टि कर सकता है कि वह मान्य है, समाप्त हो चुका है या रद्द किया गया है।</p><h2>अकादमी Vision 2030 का समर्थन कैसे करती है?</h2><p>Vision 2030 का लक्ष्य 2030 तक किंगडम में सालाना 150 मिलियन यात्राएँ हैं, और यह सऊदी मानव पूंजी को उस विकास के केंद्र में रखता है। Altus Advisory द्विभाषी लर्निंग पाथ, मूल्यांकित दक्षता और ऐसे प्रमाणन के ज़रिए अकादमी को इन लक्ष्यों से जोड़ता है, जिस पर सऊदी अरब और GCC के होटल भरोसा कर सकें।</p><p>होटल मालिक और ऑपरेटर <a href="/en/hotels">अपनी प्रॉपर्टी के लिए प्रशिक्षण सेट अप कर सकते हैं</a> या <a href="/en/contact">रियाद में अकादमी टीम से बात कर सकते हैं</a>।</p>',
      'cta_label' => 'कोर्स कैटलॉग देखें',
      'meta_title' => 'सऊदी अरब में होटल स्टाफ प्रशिक्षण | Hospitality Academy',
      'meta_description' => 'Altus Advisory की ओर से सऊदी अरब में होटल स्टाफ प्रशिक्षण: भूमिका-आधारित सीखना, व्यावहारिक मूल्यांकन और अरबी व अंग्रेज़ी में सत्यापन-योग्य प्रमाणपत्र।',
      'focus_keyword' => 'सऊदी अरब में होटल स्टाफ प्रशिक्षण',
    ),
    'about' => 
    array (
      'title' => 'Hospitality Academy के बारे में',
      'subtitle' => 'रियाद में Altus Advisory की सार्वजनिक प्रशिक्षण अकादमी: सामग्री के पीछे कौन है, इसे कैसे स्वीकृत किया जाता है, और हम क्या दावा करेंगे और क्या नहीं।',
      'body' => '<h2>Hospitality Academy कौन चलाता है?</h2><p>Hospitality Academy का संचालन Altus Advisory करता है, जो रियाद, सऊदी अरब किंगडम में मुख्यालय वाली एक बुटीक रणनीति फ़र्म है और GCC व MENA में ग्राहकों को सेवा देती है। Altus दो एकीकृत प्रभागों, Hospitality Solutions और Business Growth Solutions, के माध्यम से काम करता है, और अकादमी वह ज़रिया है जिससे इसके संचालन मानक सीधे होटल टीमों तक पहुँचते हैं।</p><h2>प्रशिक्षण सामग्री किस अनुभव पर आधारित है?</h2><p>सामग्री Altus के संस्थापकों के संचालन मानकों पर आधारित है, जिनका संयुक्त नेतृत्व अनुभव 60 वर्षों से अधिक है, जो Marriott, IHG, Starwood और Accor सिस्टम के भीतर और स्वतंत्र होटलों में प्राप्त हुआ। प्रशिक्षण मानक संचालन प्रक्रियाओं से शुरू होता है, जैसे वे शिफ़्ट पर की जाती हैं, न कि किसी सामान्य कोर्स लाइब्रेरी से।</p><h2>अकादमी का altus प्लेटफ़ॉर्म से क्या संबंध है?</h2><p>अकादमी altus Hospitality Knowledge &amp; Performance प्लेटफ़ॉर्म का सार्वजनिक प्रवेश द्वार है। प्लेटफ़ॉर्म के भीतर होटल भूमिका के अनुसार प्रशिक्षण सौंपते हैं, सैद्धांतिक और व्यावहारिक मूल्यांकन चलाते हैं, दक्षता की कमियों और कार्य योजनाओं को ट्रैक करते हैं, और हर कर्मचारी की तैयारी देखते हैं। एक नियंत्रित AI सहायक स्टाफ के प्रश्नों का उत्तर केवल स्वीकृत सामग्री से देता है और जब वह सामग्री किसी प्रश्न को कवर नहीं करती तो यह बता देता है।</p><h2>प्रशिक्षण सामग्री को कैसे स्वीकृत किया जाता है?</h2><p>हर पाठ, प्रक्रिया और मूल्यांकन शिक्षार्थियों के देखने से पहले एक नियंत्रित समीक्षा से गुज़रता है।</p><ol><li>लेखक एक ड्राफ़्ट तैयार करता है।</li><li>ड्राफ़्ट को आंतरिक स्वीकृति मिलती है।</li><li>ड्राफ़्ट को गुणवत्ता स्वीकृति मिलती है।</li><li>सामग्री प्रकाशित की जाती है और उसका संस्करण दर्ज किया जाता है।</li></ol><p>लेखक अपने काम को स्वयं स्वीकृत नहीं कर सकते, और पिछले संस्करण रिकॉर्ड में रहते हैं ताकि ऑडिटर देख सके कि किसी भी तारीख को कौन-सा मानक लागू था।</p><h2>अकादमी किन सिद्धांतों पर चलती है?</h2><p>अकादमी उन्हीं सिद्धांतों का पालन करती है जिन्हें Altus Advisory हर कार्य में लागू करता है।</p><ul><li>अनुमान से ऊपर प्रमाण: क्षमता मूल्यांकन से दिखाई जाती है, उपस्थिति से मान नहीं ली जाती।</li><li>ऐसे मानक जो हर शिफ़्ट में कायम रहें, अरबी, अंग्रेज़ी और होटल स्टाफ द्वारा प्रयुक्त कार्यबल भाषाओं में।</li><li>कार्य से आगे की साझेदारी: जुड़ाव समाप्त होने के बाद भी ज्ञान ग्राहक संगठन के भीतर रहता है।</li><li>सऊदीकरण और युवा सशक्तिकरण के लिए Vision 2030 के लक्ष्यों के अनुरूप सऊदी मानव पूंजी का समर्थन।</li></ul><h2>अकादमी क्या दावा नहीं करती?</h2><p>यह साइट कोई पास दर, ग्राहक समर्थन या मान्यता संबंधी दावे प्रकाशित नहीं करती। प्रमाणपत्र ठीक वही बताता है जो वह दर्ज करता है: किसने कौन-सा कोर्स या प्रोग्राम, किस तारीख को, किस परिणाम के साथ पूरा किया, और क्या वह अभी भी मान्य है। पढ़ें <a href="/en/certificates">प्रमाणन कैसे काम करता है</a>, या <a href="/en/altus">Altus Advisory और इसकी सेवाओं</a> के बारे में और जानें।</p>',
      'cta_label' => 'देखें प्रमाणन कैसे काम करता है',
      'meta_title' => 'रियाद हॉस्पिटैलिटी प्रशिक्षण अकादमी | Altus Advisory',
      'meta_description' => 'Hospitality Academy, Altus Advisory की रियाद स्थित हॉस्पिटैलिटी प्रशिक्षण अकादमी है, जो ऑपरेटर-स्तरीय मानकों और नियंत्रित समीक्षा पर आधारित है।',
      'focus_keyword' => 'रियाद में हॉस्पिटैलिटी प्रशिक्षण अकादमी',
