    'hotels-training' => 
    array (
      'title' => 'विभाग के अनुसार होटल स्टाफ प्रशिक्षण प्रोग्राम',
      'subtitle' => 'होटल के हर विभाग को किस चीज़ का प्रशिक्षण दिया जाता है, किस क्रम में, और कर्मचारी के बिना निगरानी काम करने से पहले क्षमता की पुष्टि कैसे होती है।',
      'body' => '<h2>होटल के हर विभाग को किस प्रशिक्षण की ज़रूरत है?</h2><p>हर विभाग मुख्य पाठ्यक्रम के भीतर अपने ट्रैक का पालन करता है, जिसे Altus Advisory ने रियाद में क्षेत्र-परीक्षित संचालन मानकों से विकसित किया है। सामग्री पेशेवर क्षेत्र, ट्रैक, मॉड्यूल और पाठ के रूप में संरचित है, जिसके बाद मूल्यांकन और प्रमाणन होता है, ताकि हर भूमिका का एक निर्धारित मार्ग हो।</p><ul><li><strong>फ्रंट ऑफ़िस:</strong> आगमन और प्रस्थान, अतिथि पंजीकरण और गोपनीयता, कमरा आवंटन, शिकायत निपटान, अपसेलिंग और नाइट ऑडिट।</li><li><strong>हाउसकीपिंग:</strong> कमरा सफ़ाई का क्रम, बिस्तर और बाथरूम मानक, रसायन सुरक्षा, खोया-पाया, लॉन्ड्री, सार्वजनिक क्षेत्र और निरीक्षण।</li><li><strong>फ़ूड एंड बेवरेज:</strong> सेवा क्रम, स्वागत और बैठाना, टेबल और पेय सेवा, बैंक्वेट और पॉइंट ऑफ़ सेल प्रक्रिया।</li><li><strong>किचन:</strong> खाद्य सुरक्षा, तापमान नियंत्रण, भंडारण और प्राप्ति, एलर्जेन प्रबंधन, चाकू सुरक्षा और अपशिष्ट नियंत्रण।</li><li><strong>सेल्स, रेवेन्यू और आरक्षण:</strong> सेल्स और मार्केटिंग, आरक्षण प्रक्रिया, डिस्ट्रीब्यूशन और रेवेन्यू के मूल सिद्धांत।</li><li><strong>अतिथि अनुभव, गुणवत्ता और ऑडिट:</strong> सेवा रिकवरी, ब्रांड और SOP अनुपालन, और गुणवत्ता निरीक्षण।</li><li><strong>सुरक्षा और संरक्षा:</strong> हर कर्मचारी के लिए अग्नि सुरक्षा, आपातकालीन प्रतिक्रिया और सुरक्षा प्रक्रिया।</li></ul><h2>होटल स्टाफ प्रशिक्षण किस क्रम में दिया जाता है?</h2><p>पहले सुरक्षा और बुनियादी बातें, फिर भूमिका कौशल, फिर उसी मानक का मूल्यांकन।</p><ol><li>हर कर्मचारी के लिए होटल के मूल सिद्धांत, प्रॉपर्टी इंडक्शन और सुरक्षा</li><li>भूमिका की पूर्व-आवश्यकताएँ, जैसे हाउसकीपिंग में रसायन सुरक्षा या किचन में खाद्य सुरक्षा और एलर्जेन प्रबंधन</li><li>वीडियो, PDF, स्लाइड या ऑडियो में छोटे व्यावहारिक पाठों वाले भूमिका मॉड्यूल</li><li>एक सैद्धांतिक मूल्यांकन, फिर सुपरवाइज़र द्वारा व्यावहारिक मूल्यांकन</li><li>एक प्रमाणपत्र, या कमी मिलने पर कार्य योजना और पुनर्मूल्यांकन</li></ol><h2>क्या प्रशिक्षण हमारे अपने होटल मानकों का पालन कर सकता है?</h2><p>हाँ। प्लेटफ़ॉर्म हर प्रॉपर्टी के लिए व्हाइट-लेबल है, और आपके स्वीकृत SOP, नीतियाँ और चेकलिस्ट पाठ्यक्रम के साथ रहती हैं, और हर संस्करण के सामने स्टाफ की स्वीकृति दर्ज होती है। AI सहायक स्टाफ के प्रश्नों का उत्तर केवल उसी स्वीकृत सामग्री से देता है।</p><h2>क्या प्रशिक्षण उन कर्मचारियों के लिए उपलब्ध है जो अरबी या अंग्रेज़ी नहीं पढ़ते?</h2><p>पाठ अरबी और अंग्रेज़ी में द्विभाषी हैं, और स्टाफ वर्कस्पेस सऊदी अरब के होटलों में काम करने वाली बहुराष्ट्रीय टीमों के लिए हिंदी, उर्दू, फ़िलिपिनो, बांग्ला, नेपाली और मलयालम को भी सपोर्ट करता है।</p><p><a href="/en/courses">पूरा कोर्स कैटलॉग</a> देखें, <a href="/en/learning-paths">भूमिका के अनुसार लर्निंग पाथ</a> अपनाएँ, या पढ़ें <a href="/en/hotels">होटल प्लेटफ़ॉर्म को कैसे लागू करते हैं</a>।</p>',
      'cta_label' => 'पूरा कैटलॉग देखें',
      'meta_title' => 'विभाग के अनुसार होटल स्टाफ प्रशिक्षण प्रोग्राम | KSA',
      'meta_description' => 'फ्रंट ऑफ़िस से किचन तक, विभाग के अनुसार होटल स्टाफ प्रशिक्षण प्रोग्राम, सऊदी अरब की टीमों के लिए व्यावहारिक मूल्यांकन और प्रमाणन के साथ।',
      'focus_keyword' => 'होटल स्टाफ प्रशिक्षण प्रोग्राम',
