    array (
      'title' => 'होटल प्रशिक्षण प्रमाणपत्र और सत्यापन',
      'subtitle' => 'Hospitality Academy का प्रमाणपत्र क्या दर्ज करता है, कब जारी होता है, और नियोक्ता कुछ ही सेकंड में कैसे जाँच सकता है कि वह असली और वर्तमान है।',
      'body' => '<h2>Hospitality Academy का प्रमाणपत्र कब जारी होता है?</h2><p>प्रमाणपत्र तब जारी होता है जब शिक्षार्थी किसी कोर्स के सभी अनिवार्य पाठ पूरे करता है और उस कोर्स के लिए तय पास अंक या उससे अधिक के साथ उसका मूल्यांकन पास करता है। प्रोग्राम प्रमाणपत्र तब जारी होता है जब प्रोग्राम का हर कोर्स पूरा हो जाता है। प्रमाणन को उपस्थिति नहीं, बल्कि मूल्यांकित क्षमता दर्शाने के लिए बनाया गया है।</p><h2>होटल प्रशिक्षण प्रमाणपत्र क्या दर्ज करता है?</h2><p>हर प्रमाणपत्र वही तथ्य दर्ज करता है जिनकी नियोक्ता को ज़रूरत होती है, इससे अधिक कुछ नहीं।</p><ul><li>शिक्षार्थी का नाम</li><li>पूरा किया गया कोर्स या प्रोग्राम</li><li>पूरा होने की तारीख और अंतिम स्कोर</li><li>एक अद्वितीय प्रमाणपत्र नंबर, सत्यापन कोड और QR कोड</li><li>समाप्ति तिथि, जहाँ विषय को समय-समय पर दोहराने की ज़रूरत हो, जैसे सुरक्षा और खाद्य सुरक्षा</li></ul><h2>मैं होटल प्रशिक्षण प्रमाणपत्र का सत्यापन कैसे करूँ?</h2><p>सार्वजनिक सत्यापन पेज का उपयोग करें। किसी अकाउंट की ज़रूरत नहीं है।</p><ol><li><a href="/en/verify">प्रमाणपत्र सत्यापन पेज</a> खोलें।</li><li>प्रमाणपत्र पर छपा सत्यापन कोड दर्ज करें, या उसका QR कोड स्कैन करें।</li><li>लौटाई गई स्थिति पढ़ें: मान्य, समाप्त, रद्द या नहीं मिला।</li></ol><p>मान्य परिणाम शिक्षार्थी का नाम, विषय और जारी होने की तारीख दिखाता है, और व्यक्ति के बारे में और कुछ नहीं।</p><h2>कोई प्रमाणपत्र रद्द क्यों दिख सकता है?</h2><p>प्रमाणपत्र रद्द किया जाता है यदि वह गलती से जारी हुआ हो, यदि उसके पीछे का मूल्यांकन परिणाम अमान्य पाया जाए, या जारी करने वाले संगठन के अनुरोध पर। रद्द प्रमाणपत्र सत्यापन-योग्य बना रहता है और गायब होने के बजाय रद्द स्थिति ही लौटाता रहता है, ताकि पुरानी प्रति को वर्तमान के रूप में प्रस्तुत न किया जा सके।</p><h2>प्रमाणपत्र कौन जारी करता है?</h2><p>प्रमाणपत्र altus Hospitality Knowledge &amp; Performance प्लेटफ़ॉर्म के माध्यम से जारी होते हैं, जिसका संचालन रियाद, सऊदी अरब में Altus Advisory करता है। प्रमाणपत्र किसी विशेष व्यक्ति द्वारा किसी विशेष तारीख को किसी विशेष कोर्स या प्रोग्राम के पूरा होने को दर्ज करता है। यह कोई लाइसेंस, नियामक स्वीकृति या यह कथन नहीं है कि धारक किसी विशेष भूमिका के लिए योग्य है।</p><p>उपलब्ध <a href="/en/programs">प्रमाणन प्रोग्राम</a> देखें या अपने होटल स्टाफ को प्रमाणित करने के बारे में <a href="/en/contact">अकादमी टीम से पूछें</a>।</p>',
      'cta_label' => 'प्रमाणपत्र सत्यापित करें',
      'meta_title' => 'होटल प्रशिक्षण प्रमाणपत्र सत्यापित करें | Hospitality Academy',
      'meta_description' => 'कोड या QR से Hospitality Academy का होटल प्रशिक्षण प्रमाणपत्र सत्यापित करें, और देखें प्रमाणपत्र क्या दर्ज करता है, कब समाप्त होता है और क्यों रद्द हो सकता है।',
      'focus_keyword' => 'होटल प्रशिक्षण प्रमाणपत्र सत्यापन',
