    'contact' => 
    array (
      'title' => 'Hospitality Academy से संपर्क करें',
      'subtitle' => 'हमें अपनी प्रॉपर्टी और अपनी टीम के बारे में बताएँ, और हम ब्रोशर के बजाय एक संरचना के साथ जवाब देंगे।',
      'body' => '<h2>मैं अपनी प्रॉपर्टी के लिए होटल प्रशिक्षण का अनुरोध कैसे करूँ?</h2><p>रियाद या किंगडम में कहीं भी होटल प्रशिक्षण के बारे में अपनी पूछताछ इस पेज के फ़ॉर्म से भेजें। रियाद, सऊदी अरब किंगडम में Altus Advisory की Hospitality Academy टीम का एक सदस्य कॉल तय करने के लिए जवाब देगा। कोई स्वचालित ईमेल क्रम नहीं है, और आपका विवरण किसी तीसरे पक्ष को नहीं दिया जाता।</p><h2>मुझे अपनी पूछताछ में क्या शामिल करना चाहिए?</h2><p>कुछ तथ्यों से हम सामान्य प्रस्तुति के बजाय एक कार्य-योग्य संरचना के साथ जवाब दे पाते हैं।</p><ul><li>शामिल प्रॉपर्टी और शहर</li><li>वे विभाग जिनसे आप शुरुआत करना चाहते हैं</li><li>हर विभाग में कर्मचारियों की अनुमानित संख्या</li><li>आपके स्टाफ को जिन भाषाओं की ज़रूरत है: अरबी, अंग्रेज़ी, या कार्यबल भाषाएँ जैसे हिंदी, उर्दू, फ़िलिपिनो, बांग्ला, नेपाली या मलयालम</li><li>कोई समय-सीमा, जैसे प्री-ओपनिंग या निरीक्षण</li></ul><h2>संपर्क करने के बाद क्या होता है?</h2><p>प्रक्रिया छोटी है और इसे स्वचालन नहीं, लोग संभालते हैं।</p><ol><li>हम परिचयात्मक कॉल तय करने के लिए जवाब देते हैं।</li><li>हम आपकी प्रॉपर्टी, नौकरी की भूमिकाओं और वर्तमान मानकों पर चर्चा करते हैं।</li><li>हम आपकी टीम के लिए विभागों, भूमिकाओं और अनिवार्य प्रशिक्षण की संरचना प्रस्तावित करते हैं।</li></ol><h2>क्या मैं प्रशिक्षण के अलावा किसी और विषय पर Altus Advisory से संपर्क कर सकता हूँ?</h2><p>हाँ। Altus Advisory सऊदी अरब और GCC में होटल मालिकों और निवेशकों को होटल विकास और मालिक प्रतिनिधित्व, प्री-ओपनिंग सहायता, संचालन, अतिथि अनुभव, वाणिज्यिक प्रदर्शन और व्यापक बिज़नेस विकास पर भी सलाह देता है। पढ़ें <a href="/en/altus">Altus Advisory और इसकी सेवाओं</a> के बारे में।</p><h2>प्रमाणपत्र से जुड़े प्रश्न के लिए मैं कहाँ जाऊँ?</h2><p>यह पुष्टि करने के लिए कि कोई प्रमाणपत्र असली है, सीधे <a href="/en/verify">प्रमाणपत्र सत्यापन पेज</a> का उपयोग करें; किसी पूछताछ की ज़रूरत नहीं है। अपने लर्निंग रिकॉर्ड की प्रति या उसमें सुधार का अनुरोध करने के लिए, अपने नियोक्ता के एडमिनिस्ट्रेटर से संपर्क करें या इस पेज के माध्यम से हमें लिखें।</p><p>लिखने से पहले, आपके लिए यह देखना उपयोगी हो सकता है कि <a href="/en/hotels">होटलों के लिए प्लेटफ़ॉर्म कैसे काम करता है</a> या <a href="/en/courses">कोर्स कैटलॉग</a> ब्राउज़ करें।</p>',
      'cta_label' => 'अपनी पूछताछ भेजें',
      'meta_title' => 'संपर्क करें: रियाद में होटल प्रशिक्षण | Altus Advisory',
      'meta_description' => 'रियाद और पूरे सऊदी अरब में होटल प्रशिक्षण के लिए Altus Advisory की Hospitality Academy से संपर्क करें। अपनी प्रॉपर्टी, विभाग और समय-सीमा बताएँ।',
      'focus_keyword' => 'रियाद में होटल प्रशिक्षण',
