      'title' => 'गोपनीयता नीति',
      'subtitle' => 'अकादमी क्या संग्रहीत करती है, क्यों, इसे कौन देख सकता है और इसे कितने समय तक रखा जाता है।',
      'body' => '<h2>यह नीति किस पर लागू होती है</h2><p>यह नीति Hospitality Academy पर लागू होती है, जो रियाद, सऊदी अरब किंगडम में Altus Advisory द्वारा संचालित प्रशिक्षण अकादमी है, और उन शिक्षार्थियों पर जो इसे अपने नियोक्ता के माध्यम से या सीधे उपयोग करते हैं।</p><h2>क्या एकत्र किया जाता है</h2><p>किसी शिक्षार्थी के लिए अकादमी संग्रहीत करती है:</p><ul><li>नाम, कार्य ईमेल और मोबाइल नंबर, जहाँ दिया गया हो</li><li>नियोक्ता, प्रॉपर्टी, विभाग और नौकरी की भूमिका</li><li>लर्निंग रिकॉर्ड: नामांकन, पाठ प्रगति, मूल्यांकन प्रयास और स्कोर, प्रमाणपत्र और प्रक्रिया स्वीकृतियाँ</li></ul><h2>इसे क्यों एकत्र किया जाता है</h2><p>जानकारी का उपयोग इसके लिए होता है:</p><ul><li>प्रशिक्षण देना</li><li>यह दर्ज करना कि प्रशिक्षण पूरा हुआ या नहीं</li><li>प्रमाणपत्र जारी और सत्यापित करना</li><li>नियोक्ता को अपने कार्यबल की अनुपालन स्थिति देखने देना</li></ul><p>कुछ भी बेचा नहीं जाता, और किसी चीज़ का उपयोग विज्ञापन के लिए नहीं होता।</p><h2>प्रक्रिया स्वीकृतियाँ</h2><p>स्वीकृति उपयोगकर्ता, सटीक प्रक्रिया संस्करण, टाइमस्टैम्प और मूल नेटवर्क पता दर्ज करती है। यह जानबूझकर है: जो स्वीकृति किसी व्यक्ति, संस्करण और क्षण से जोड़ी न जा सके, वह किसी बात का प्रमाण नहीं है।</p><h2>लर्निंग रिकॉर्ड कौन देख सकता है</h2><p>लर्निंग रिकॉर्ड इन्हें दिख सकता है:</p><ul><li>शिक्षार्थी</li><li>शिक्षार्थी का लाइन मैनेजर</li><li>उसी संगठन के भीतर विभाग, प्रॉपर्टी और संगठन एडमिनिस्ट्रेटर</li><li>एक अकादमी एडमिनिस्ट्रेटर</li></ul><p>कोई भी संगठन किसी दूसरे संगठन का डेटा नहीं देख सकता।</p><h2>प्रतिधारण</h2><p>लर्निंग रिकॉर्ड और प्रमाणपत्र अकाउंट सक्रिय रहने तक रखे जाते हैं, और उसके बाद तब तक जब तक जारी करने वाले संगठन को ऑडिट के लिए उनकी ज़रूरत हो। प्रमाणपत्र रिकॉर्ड अनिश्चित काल तक रखा जाता है ताकि सत्यापन काम करता रहे।</p><h2>आपके अनुरोध</h2><p>शिक्षार्थी अपने नियोक्ता के एडमिनिस्ट्रेटर के माध्यम से या <a href="/en/contact">संपर्क पेज</a> से सीधे अकादमी से संपर्क करके अपने रिकॉर्ड की प्रति या उसमें सुधार का अनुरोध कर सकता है। <a href="/en/terms">उपयोग की शर्तें</a> अकाउंट और प्रमाणपत्रों के नियम बताती हैं।</p>',
