      'meta_description' => 'Hospitality Academy गोपनीयता नीति: शिक्षार्थी का कौन-सा डेटा क्यों एकत्र होता है, लर्निंग रिकॉर्ड कौन देख सकता है, और रिकॉर्ड व प्रमाणपत्र कितने समय रखे जाते हैं।',
