      'title' => 'उपयोग की शर्तें',
      'subtitle' => 'अकादमी के उपयोग और उसके द्वारा जारी प्रमाणपत्रों पर लागू होने वाली शर्तें।',
      'body' => '<h2>दायरा</h2><p>ये शर्तें रियाद, सऊदी अरब किंगडम में Altus Advisory द्वारा संचालित Hospitality Academy पर, और इसके माध्यम से जारी प्रमाणपत्रों पर लागू होती हैं।</p><h2>अकाउंट</h2><p>एक अकाउंट एक नामित व्यक्ति का होता है।</p><ul><li>अकाउंट साझा करने की अनुमति नहीं है।</li><li>किसी दूसरे व्यक्ति की ओर से प्रशिक्षण पूरा करने की अनुमति नहीं है।</li></ul><p>इनमें से कोई भी व्यवहार उससे मिले किसी भी प्रमाणपत्र को अमान्य कर देता है और अकाउंट निलंबित करने का आधार है।</p><h2>मूल्यांकन</h2><p>मूल्यांकन प्रयास टाइमस्टैम्प और प्रयास संख्या के साथ दर्ज किए जाते हैं। प्रयास सीमा, समय सीमा और प्रश्नों का यादृच्छिक क्रम हर मूल्यांकन के लिए कॉन्फ़िगर किए अनुसार लागू होते हैं। इन नियंत्रणों को दरकिनार करके प्राप्त परिणाम शून्य है।</p><h2>प्रमाणपत्र</h2><p>प्रमाणपत्र किसी विशेष व्यक्ति द्वारा किसी विशेष तारीख को किसी विशेष कोर्स या प्रोग्राम के पूरा होने को दर्ज करता है। यह कोई लाइसेंस, नियामक स्वीकृति, या यह कथन नहीं है कि धारक किसी विशेष भूमिका के लिए योग्य है। ऐसा कोई भी उपयोग इन शर्तों से बाहर है। प्रमाणपत्र की स्थिति <a href="/en/verify">सत्यापन पेज</a> पर जाँची जा सकती है।</p><h2>सामग्री</h2><p>अकादमी द्वारा प्रकाशित कोर्स सामग्री और प्रक्रियाएँ अकादमी की या उन्हें तैयार करने वाले संगठन की संपत्ति रहती हैं। किसी संगठन द्वारा अपलोड की गई प्रक्रियाएँ उसी संगठन की संपत्ति रहती हैं और किसी अन्य संगठन के साथ साझा नहीं की जातीं।</p><h2>उपलब्धता</h2><p>अकादमी सेवा को लगातार उपलब्ध रखने का प्रयास करती है, लेकिन निर्बाध एक्सेस की गारंटी नहीं देती। जहाँ नियोजित रखरखाव से एक्सेस बाधित होने की संभावना हो, उसकी घोषणा पहले से की जाती है।</p><h2>संबंधित नीतियाँ</h2><p>व्यक्तिगत डेटा को कैसे संभाला जाता है, इसका वर्णन <a href="/en/privacy">गोपनीयता नीति</a> में है।</p>',
      'cta_label' => 'गोपनीयता नीति पढ़ें',
      'meta_title' => 'उपयोग की शर्तें | Altus Advisory की Hospitality Academy',
      'meta_description' => 'Hospitality Academy उपयोग की शर्तें: अकाउंट और मूल्यांकन के नियम, प्रमाणपत्र क्या बताता है और क्या नहीं, सामग्री का स्वामित्व और उपलब्धता।',
      'focus_keyword' => 'उपयोग की शर्तें',
