  'articles' => 
  array (
    'how-to-train-a-new-front-desk-agent' => 
    array (
      'title' => 'नए फ़्रंट डेस्क एजेंट को उसके पहले दो हफ़्तों में कैसे प्रशिक्षित करें',
      'excerpt' => 'दो हफ़्ते का एक क्रम जो नए फ़्रंट ऑफ़िस एजेंट को होटल की रक्षा करने वाले सुरक्षा और निजता प्रशिक्षण को छोड़े बिना बिना-निगरानी वाली शिफ़्ट तक पहुँचाता है।',
      'body' => '<p>नए फ़्रंट डेस्क एजेंट को आमतौर पर या तो बहुत जल्दी या बहुत देर से शिफ़्ट पर लगाया जाता है। बहुत जल्दी लगाने पर वह मानक सीखने से पहले होटल की बुरी आदतें सीख लेता है। बहुत देर से लगाने पर वह पंद्रह दिन बिना किसी ज़िम्मेदारी के सिर्फ़ साथ-साथ घूमता है, जिससे बहुत कम सीखता है। दो हफ़्ते का एक तय क्रम इन दोनों से बचाता है।</p><h2>पहला और दूसरा दिन: डेस्क नहीं, प्रॉपर्टी</h2><p>आपातकालीन निकास, असेंबली पॉइंट, उसका मैनेजर कौन है, उसका लॉकर कहाँ है, और रिपोर्टिंग की व्यवस्था। अग्नि सुरक्षा और आपातकालीन प्रतिक्रिया पहले ही दिन सौंपी जाती है और सातवें दिन तक पूरी करनी होती है, क्योंकि जो एजेंट मेहमान को सीढ़ियों तक का रास्ता नहीं बता सकता, वह जोखिम है, चाहे वह चेक-इन कितना भी अच्छा करता हो।</p><h2>तीसरे से पाँचवें दिन: क्रम</h2><p>फ़्रंट ऑफ़िस के मूल सिद्धांत, टेलीफ़ोन शिष्टाचार, फिर चेक-इन और चेक-आउट अलग-अलग कोर्स के रूप में। एजेंट आगमन की एक पूरी लहर और प्रस्थान की एक पूरी लहर को साथ रहकर देखता है, और सिर्फ़ देखने के बजाय किसी अनुभवी एजेंट के साथ चेकलिस्ट चलाता है।</p><h2>छठे से आठवें दिन: सिस्टम और रिकॉर्ड</h2><p>प्रॉपर्टी मैनेजमेंट सिस्टम का प्रशिक्षण, मेहमान पंजीकरण और मेहमान की निजता। निजता बाद में सोचने वाली बात नहीं है: कमरा नंबर को लेकर अनुशासन, कॉल करने वाले को क्या बताया जा सकता है, और पहचान दस्तावेज़ों को कैसे संभाला जाता है, यह सब एजेंट को बिना निगरानी सिस्टम एक्सेस मिलने से पहले सीखना होता है।</p><h2>नौवें से ग्यारहवें दिन: निगरानी में</h2><p>एजेंट डेस्क पर काम करता है, सुपरवाइज़र मौजूद रहता है लेकिन ज़रूरत न हो तो दख़ल नहीं देता। हर अपवाद, पहला कठिन मेहमान और पहली सिस्टम त्रुटि एक और कोर्स से कहीं ज़्यादा सिखाते हैं।</p><h2>बारहवें से चौदहवें दिन: मूल्यांकन और स्वतंत्र शिफ़्ट</h2><p>मूल्यांकन पूरे करें, सुपरवाइज़र के साथ चेकलिस्ट के परिणामों की समीक्षा करें, और पुष्टि करें कि अनिवार्य प्रशिक्षण पूरा के रूप में दर्ज है। बिना निगरानी वाली शिफ़्ट पर भेजना एक ऐसा निर्णय है जिसके साथ किसी का नाम जुड़ा होता है और जो कर्मचारी के रिकॉर्ड में दर्ज होता है, यह मान लेना नहीं कि पर्याप्त समय बीत गया है।</p><h2>इसके बाद क्या</h2><p>दूसरे महीने में कमरा आवंटन, शिकायत निपटारा और अपसेलिंग, और नाइट ऑडिट तभी जब दिन का क्रम पूरी तरह स्वाभाविक हो जाए।</p>',
    ),
    'writing-a-hotel-sop-people-actually-follow' => 
    array (
      'title' => 'होटल का ऐसा SOP लिखना जिसका लोग वास्तव में पालन करें',
      'excerpt' => 'ज़्यादातर होटल प्रक्रियाएँ एक ही चार कारणों से विफल होती हैं। दस्तावेज़ प्रकाशित होने से पहले इनमें से हर एक को ठीक किया जा सकता है।',
      'body' => '<p>ज़्यादातर होटलों में प्रक्रियाएँ होती हैं। बहुत कम होटलों में ऐसी प्रक्रियाएँ होती हैं जो शिफ़्ट पर होने वाले काम को बदल दें। यह कमी लगभग हमेशा लेखन में होती है, टीम में नहीं।</p><h2>यह चरणों के बजाय परिणाम बताता है</h2><p>“सुनिश्चित करें कि कमरा आवश्यक मानक पर खरा उतरे” कोई प्रक्रिया नहीं है। “बाथरूम को इस क्रम में साफ़ करें: शीशा, बेसिन, बाथ या शावर, टॉयलेट सबसे आख़िर में, फिर फ़र्श” एक प्रक्रिया है। अगर किसी वाक्य पर अमल नहीं किया जा सकता, तो उसकी जगह गुणवत्ता मानक वाले भाग में है, प्रक्रिया में नहीं।</p><h2>इसमें एस्केलेशन का रास्ता नहीं है</h2><p>हर प्रक्रिया के सामने कभी न कभी ऐसा मामला आता है जिसकी उसने कल्पना नहीं की थी, आमतौर पर सबसे बुरे समय पर। जिस प्रक्रिया में एस्केलेशन का तय रास्ता नहीं होता, वह कर्मचारी को खुद कोई रास्ता गढ़ने पर मजबूर करती है, और गढ़ा हुआ रास्ता ही घटना की रिपोर्ट तक ले जाता है। स्पष्ट लिखें कि किसे बुलाया जाए, किस बात के लिए, और कितनी जल्दी।</p><h2>कोई नहीं बता सकता कि उसने कौन-सा संस्करण पढ़ा</h2><p>साझा फ़ोल्डर में रखी बिना तारीख़ की प्रक्रिया की पुष्टि नहीं की जा सकती। हर प्रक्रिया को एक संस्करण संख्या, लेखक, अनुमोदक, लागू होने की तारीख़ और समीक्षा की तारीख़ दें, पिछले संस्करणों को पढ़ने योग्य रखें, और लोगों से हर नए संस्करण की पुष्टि (एक्नॉलेजमेंट) करने को कहें। तब मैनेजर ऑडिट के दौरान उस एकमात्र सवाल का जवाब दे सकता है जो मायने रखता है: लागू संस्करण किसने पढ़ा था।</p><h2>इसे किसी ऐसे व्यक्ति ने लिखा जो यह काम नहीं करता</h2><p>दफ़्तर में लिखी गई और किसी विभाग को सौंपी गई प्रक्रिया में आमतौर पर कोई ऐसा चरण छूट जाता है जिसे वह विभाग छोड़ नहीं सकता। ड्राफ़्ट उन लोगों के साथ लिखें जो यह कार्य करते हैं, एक बार उनके साथ इसे व्यवहार में चलाकर देखें, और पहली विफलता के बाद नहीं बल्कि प्रकाशित करने से पहले इसे सुधारें।</p><h2>प्रकाशन से पहले एक परीक्षण</h2><p>ड्राफ़्ट किसी ऐसे व्यक्ति को दें जिसने यह कार्य कभी नहीं किया हो, और उससे इसका ठीक-ठीक पालन करने को कहें। वह जो भी सवाल पूछे, वह एक छूटा हुआ चरण है।</p>',
    ),
    'hotel-food-safety-records-that-survive-an-inspection' => 
    array (
      'title' => 'होटल के खाद्य सुरक्षा रिकॉर्ड जो निरीक्षण में खरे उतरें',
      'excerpt' => 'एक पूरा तापमान लॉग कैसा दिखता है, खाली खाने सबसे आम कमी क्यों होते हैं, और काग़ज़ी काम के बजाय मूल कारण को कैसे ठीक करें।',
      'body' => '<p>कोई रसोई वास्तव में सुरक्षित होते हुए भी रिकॉर्ड के मामले में विफल हो सकती है। निरीक्षक सुरक्षा को चख नहीं सकता, इसलिए लॉग ही सबूत है, और अधूरे लॉग को काग़ज़ी काम की कमी नहीं बल्कि नियंत्रण की कमी माना जाता है।</p><h2>एक पूरे लॉग में क्या होता है</h2><p>हर शिफ़्ट की शुरुआत में एक कैलिब्रेशन प्रविष्टि। ठंडे और फ़्रोज़न भंडारण का हर शिफ़्ट में दो बार रिकॉर्ड। सर्विस से पहले पकाने के तापमान की पुष्टि। हॉट होल्डिंग का हर दो घंटे पर रिकॉर्ड। दो-चरणीय लक्ष्य के सामने ठंडा करने का समय दर्ज। दोबारा गरम करने का एक बार रिकॉर्ड। और सीमा से बाहर की हर रीडिंग के सामने, नाम सहित दर्ज सुधारात्मक कार्रवाई।</p><h2>खाने खाली क्यों रह जाते हैं</h2><p>लगभग कभी इसलिए नहीं कि टीम को परवाह नहीं है। आमतौर पर इसलिए कि लॉग वहाँ रखा होता है जहाँ शेफ़ रीडिंग लेते समय खड़ा नहीं होता, क्योंकि प्रोब साझा होता है और ज़रूरत के समय उपलब्ध नहीं होता, या क्योंकि शिफ़्ट व्यस्त थी और इरादा बाद में भरने का था। शिफ़्ट के अंत में याद से भरा गया रिकॉर्ड, रिकॉर्ड नहीं है, और आमतौर पर यह साफ़ दिख जाता है।</p><h2>मूल कारण को ठीक करना</h2><p>लॉग वहाँ रखें जहाँ रीडिंग ली जाती है। हर सेक्शन को उसका अपना प्रोब दें। हर दो घंटे की हॉट होल्डिंग जाँच को साझा ज़िम्मेदारी के बजाय शिफ़्ट बोर्ड पर किसी नामित व्यक्ति की ज़िम्मेदारी बनाएँ। फिर लॉग की जाँच साप्ताहिक के बजाय रोज़ाना करें, क्योंकि अगली सुबह मिली कमी को अभी भी समझाया जा सकता है।</p><h2>प्रशिक्षण की मुख्य बात</h2><p>लॉग पूरा करने को प्रशासनिक काम नहीं, बल्कि दक्षता का हिस्सा मानें। जिस शेफ़ को सिखाया गया है कि रिकॉर्ड नियंत्रण का हिस्सा है, वह उसे रीडिंग लेते ही भरता है, और वही एकमात्र समय है जब वह सच होता है।</p>',
    ),
    'measuring-hotel-training-completion-honestly' => 
    array (
      'title' => 'होटल प्रशिक्षण की पूर्णता को ईमानदारी से मापना',
      'excerpt' => 'उपस्थिति पूर्णता क्यों नहीं है, पूर्णता का प्रतिशत उस एकमात्र कमी को क्यों छिपा सकता है जो मायने रखती है, और उसकी जगह क्या रिपोर्ट करें।',
      'body' => '<p>प्रशिक्षण रिपोर्टों को अच्छा दिखाना आसान है और उपयोगी बनाना कठिन। ज़्यादातर अंतर तीन आदतों से पैदा होता है।</p><h2>उपस्थिति पूर्णता नहीं है</h2><p>हस्ताक्षरित उपस्थिति पत्रक यह दर्ज करता है कि कोई व्यक्ति कमरे में मौजूद था। यह दर्ज नहीं करता कि वह कार्य कर सकता है। मूल्यांकन के परिणाम से जुड़ा पूर्णता रिकॉर्ड यह दर्ज करता है। दूसरे वाले की रिपोर्ट करें, और पहले वाले को केवल वहीं रखें जहाँ क्लासरूम सत्र वास्तव में आवश्यकता का हिस्सा हो।</p><h2>औसत कमी को छिपा देता है</h2><p>नब्बे प्रतिशत पूर्णता वाली प्रॉपर्टी तब तक स्वस्थ लगती है जब तक आप यह न देखें कि बचे हुए दस प्रतिशत पूरी नाइट शिफ़्ट है, या पिछले महीने शामिल हुआ हर नया कर्मचारी। विभाग, प्रॉपर्टी और व्यक्ति के अनुसार रिपोर्ट करें, और बकाया (ओवरड्यू) सूची को प्रतिशत से ऊपर रखें, क्योंकि उसी सूची पर कोई कार्रवाई कर सकता है।</p><h2>वैधता के बिना पूर्णता अनुपालन नहीं है</h2><p>सुरक्षा और खाद्य सुरक्षा प्रशिक्षण की अवधि समाप्त होती है। जो रिपोर्ट समाप्त हो चुके प्रमाणपत्र को पूरा मानती है, वह किसी रिपोर्ट के न होने से भी बदतर है, क्योंकि वह ऐसा भरोसा पैदा करती है जो उचित नहीं है। समाप्ति के क़रीब पहुँच रहे प्रमाणपत्रों को अपवाद रिपोर्ट के रूप में नहीं, बल्कि एक स्थायी मद के रूप में दिखाएँ।</p><h2>मैनेजर के सामने क्या रखें</h2><p>चार बातें: अभी कौन बकाया है, इस हफ़्ते कौन बकाया हो जाएगा, इस महीने कौन-से प्रमाणपत्र समाप्त हो रहे हैं, और किन प्रक्रियाओं के मौजूदा संस्करणों की पुष्टि नहीं हुई है। बाक़ी सब संदर्भ है।</p>',
    ),
    'training-hotel-teams-in-arabic-and-english' => 
    array (
      'title' => 'होटल टीमों को अरबी और अंग्रेज़ी में प्रशिक्षित करना, किसी भी भाषा को खोए बिना',
      'excerpt' => 'अनुवादित कोर्स द्विभाषी कोर्स क्यों नहीं होता, और व्यवहार में एक सच्चा द्विभाषी होटल प्रशिक्षण कार्यक्रम कैसा दिखता है।',
      'body' => '<p>सऊदी अरब में ज़्यादातर होटल टीमें वास्तव में द्विभाषी हैं, लेकिन एक समान रूप से नहीं। किसी हाउसकीपिंग फ़्लोर पर मुख्य रूप से अरबी में काम हो सकता है, फ़्रंट डेस्क पर मुख्य रूप से अंग्रेज़ी में, और रसोई में ऐसे मिश्रण में जो शिफ़्ट के साथ बदलता है। जो प्रशिक्षण कार्यक्रम एक ही भाषा चुनता है, वह चुपचाप टीम के एक हिस्से को बाहर कर देता है।</p><h2>अनुवाद और मूल लेखन एक जैसे नहीं हैं</h2><p>मशीन से अनुवादित कोर्स अनुवाद जैसा ही पढ़ा जाता है, और जो प्रक्रियात्मक निर्देश अटपटा लगता है, वह दबाव में ग़लत समझा जाता है। अरबी संस्करण को अरबी सामग्री के रूप में लिखें, उन शब्दों के साथ जो विभाग शिफ़्ट पर वास्तव में इस्तेमाल करता है, और अंग्रेज़ी संस्करण को अंग्रेज़ी सामग्री के रूप में। दोनों को अर्थ में एक जैसा रखें, शब्दशः नहीं।</p><h2>दाएँ से बाएँ एक लेआउट है, केवल पाठ की दिशा नहीं</h2><p>अरबी पेज, पाठ को उलट देने वाला अंग्रेज़ी पेज नहीं है। नेविगेशन, प्रगति संकेतक, चेकलिस्ट, टेबल और फ़ॉर्म फ़ील्ड, सभी को दाईं ओर से स्वाभाविक रूप से पढ़ा जाना चाहिए। अरबी इंटरफ़ेस में बाएँ से दाएँ चलने वाली क्रमांकित प्रक्रिया में लोग चरणों का क्रम ग़लत पढ़ेंगे।</p><h2>हर सत्र में सीखने वाले को चुनने दें</h2><p>भाषा हर सत्र का विकल्प होनी चाहिए, न कि साइन-अप के समय एक बार तय की गई अकाउंट सेटिंग। कोई सीखने वाला सुरक्षा कोर्स अरबी में और प्रॉपर्टी मैनेजमेंट सिस्टम का कोर्स अंग्रेज़ी में ले सकता है, क्योंकि सिस्टम खुद अंग्रेज़ी में है। भाषा बदलने पर भी प्रगति बनी रहनी चाहिए।</p><h2>वे शब्द जिनका अनुवाद नहीं होना चाहिए</h2><p>सिस्टम के फ़ील्ड नाम, रेडियो पर इस्तेमाल होने वाले कोड शब्द, और उपकरणों पर छपा कोई भी शब्द उसी भाषा में रहना चाहिए जिसमें वह काम पर दिखता है, और उसकी व्याख्या सीखने वाले की भाषा में हो। किसी ऐसे बटन लेबल का अनुवाद करना जिसे सीखने वाला स्क्रीन पर अंग्रेज़ी में देखेगा, कमी को दूर करने के बजाय एक नई कमी पैदा करता है।</p>',
    ),
    'pre-opening-hotel-training-checklist' => 
    array (
      'title' => 'प्री-ओपनिंग होटल प्रशिक्षण: पहले मेहमान से पहले क्या पूरा होना चाहिए',
      'excerpt' => 'प्रशिक्षण और प्रक्रिया से जुड़ा वह काम जिसे प्री-ओपनिंग टीम टाल नहीं सकती, इस क्रम में कि उसे कब होना है।',
      'body' => '<p>प्री-ओपनिंग एक साल के परिचालन निर्माण को कुछ महीनों में समेट देता है, और प्रशिक्षण आमतौर पर वह हिस्सा होता है जिसे टाल दिया जाता है क्योंकि वह इमारत से कम ज़रूरी लगता है। ऐसा नहीं है, क्योंकि उद्घाटन की तारीख़ नहीं खिसकती, लेकिन टीम की तैयारी खिसक जाती है।</p><h2>नब्बे दिन पहले: प्रक्रियाएँ</h2><p>जिन लोगों को प्रक्रियाओं का पालन करना है, उन्हें भर्ती करने से पहले प्रक्रियाएँ लिखें। जो विभाग बिना किसी लिखित मानक के आता है, वह अपना मानक गढ़ लेता है, और बाद में गढ़े हुए मानक को सुधारना अभी लिखने से ज़्यादा महँगा पड़ता है। हर प्रक्रिया को शुरू से ही एक स्वामी, एक अनुमोदक और समीक्षा की तारीख़ चाहिए।</p><h2>साठ दिन पहले: अनिवार्य सेट</h2><p>अग्नि सुरक्षा, आपातकालीन प्रतिक्रिया और प्रॉपर्टी इंडक्शन हर कर्मचारी को सौंपे जाएँ, जिनकी नियत तारीख़ सॉफ़्ट ओपनिंग से पहले हो, ग्रैंड ओपनिंग से पहले नहीं। हाउसकीपिंग के किसी उत्पाद को छूने से पहले रसायन सुरक्षा। रसोई के टेस्ट सर्विस चलाने से पहले खाद्य सुरक्षा।</p><h2>तीस दिन पहले: विभागीय क्रम</h2><p>हर विभाग अपना मुख्य क्रम पूरा करता है और अपनी चेकलिस्ट ट्रेनिंग रूम में नहीं, असली फ़्लोर पर चलाता है। हाउसकीपिंग टीम को पहले मेहमान से पहले वास्तविक इमारत के असली कमरे साफ़ कर लेने चाहिए, उन कमरों सहित जो अभी तैयार नहीं हुए हैं।</p><h2>चौदह दिन पहले: ड्राई रन</h2><p>एक पूरा सिम्युलेटेड दिन चलाएँ जिसमें स्टाफ़ मेहमान बनें: आगमन, रेस्टोरेंट सर्विस, एक शिकायत, एक रखरखाव कॉल और निकासी ड्रिल। इसमें जो भी कमी सामने आती है, वह वही कमी है जो अन्यथा किसी मेहमान को मिलती।</p><h2>बिक्री के लिए खोलने से पहले</h2><p>कोई भी कमरा अग्नि सुरक्षा, विद्युत या जल सुरक्षा से जुड़ी किसी खुली मद के साथ बिक्री के लिए जारी नहीं किया जाता, उद्घाटन की तारीख़ चाहे जो हो। यह निर्णय एक बार, लिखित रूप में, उस पर दबाव आने से पहले लेना होता है।</p>',
    ),
  ),
