      'question' => 'नए फ़्रंट डेस्क एजेंट को सबसे पहले क्या सीखना चाहिए?',
      'answer' => 'सबसे पहले अग्नि सुरक्षा और प्रॉपर्टी इंडक्शन, फिर फ़्रंट ऑफ़िस के मूल सिद्धांत और टेलीफ़ोन शिष्टाचार, फिर चेक-इन, चेक-आउट और मेहमान पंजीकरण, और फिर प्रॉपर्टी मैनेजमेंट सिस्टम। शिकायत निपटारा और नाइट ऑडिट बाद में आते हैं, जब बुनियादी क्रम स्वाभाविक हो जाए।',
