    'topic:hotel-sop-training#11' => 
    array (
      'question' => 'होटल SOP की समीक्षा कितनी बार की जानी चाहिए?',
      'answer' => 'बारह महीने का समीक्षा अंतराल एक आम डिफ़ॉल्ट है, और हर प्रक्रिया की अपनी समीक्षा तारीख़ होती है। किसी प्रक्रिया की समीक्षा उस हर घटना के तुरंत बाद भी होनी चाहिए जिसे वह रोकने में विफल रही, और जब भी वह उपकरण, सिस्टम या नियम बदले जिस पर वह निर्भर है।',
