    'global:#0' => 
    array (
      'question' => 'Hospitality Academy क्या है?',
      'answer' => 'Hospitality Academy एक होटल प्रशिक्षण और स्टैंडर्ड ऑपरेटिंग प्रोसीजर प्लेटफ़ॉर्म है। यह होटल विभागों के लिए भूमिका-आधारित कोर्स, संस्करण-नियंत्रित SOP लाइब्रेरी, मूल्यांकन, और ऐसे प्रमाणपत्र प्रदान करता है जिनका सार्वजनिक रूप से सत्यापन किया जा सकता है। कोर्स अरबी और अंग्रेज़ी में उपलब्ध हैं।',
    ),
    'global:#1' => 
    array (
      'question' => 'क्या कोर्स अरबी में उपलब्ध हैं?',
      'answer' => 'हाँ। हर कोर्स, पाठ, प्रक्रिया और सार्वजनिक पेज अरबी और अंग्रेज़ी में अलग-अलग लिखी गई सामग्री के रूप में मौजूद है, और अरबी इंटरफ़ेस अंग्रेज़ी का प्रतिबिंब (मिरर) नहीं, बल्कि वास्तविक दाएँ-से-बाएँ लेआउट का उपयोग करता है।',
    ),
    'global:#2' => 
    array (
      'question' => 'मैं Hospitality Academy प्रमाणपत्र का सत्यापन कैसे करूँ?',
      'answer' => 'प्रमाणपत्र पर छपा सत्यापन कोड सार्वजनिक सत्यापन पेज पर दर्ज करें। पेज सीधे चार में से एक परिणाम दिखाता है: मान्य, समाप्त, रद्द, या नहीं मिला। प्रमाणपत्र जाँचने के लिए किसी अकाउंट की आवश्यकता नहीं है।',
