      'answer' => 'हाँ। प्रशिक्षण असाइनमेंट किसी व्यक्ति, विभाग, प्रॉपर्टी, जॉब रोल या पूरे संगठन को लक्षित कर सकता है, जिसमें शुरू होने की तारीख़, नियत तारीख़, समय-सीमा से पहले रिमाइंडर, और किसी मद के बकाया होने पर लाइन मैनेजर तक एस्केलेशन शामिल हैं।',
